package com.fluxisai.subscription;
import java.math.*; import java.time.*; import java.util.*; import com.fluxisai.common.error.ResourceNotFoundException; import com.fluxisai.common.security.CurrentUser; import com.fluxisai.common.web.PageResponse; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SubscriptionService { private final SubscriptionRepository subscriptions; private final CurrentUser currentUser; public SubscriptionService(SubscriptionRepository s,CurrentUser u){subscriptions=s;currentUser=u;}
 @Transactional public SubscriptionResponse create(SubscriptionRequest r){return SubscriptionResponse.from(subscriptions.save(new Subscription(currentUser.id(),clean(r.name()),clean(r.provider()),money(r.amount()),r.currency(),r.periodicity(),r.nextChargeDate(),r.renewalDate(),r.status(),optional(r.category()),optional(r.notes()),optional(r.managementUrl()))));}
 @Transactional(readOnly=true) public SubscriptionResponse get(UUID id){return SubscriptionResponse.from(find(id));}
 @Transactional(readOnly=true) public PageResponse<SubscriptionResponse> list(Pageable p){return PageResponse.from(subscriptions.findAllByUserId(currentUser.id(),p).map(SubscriptionResponse::from));}
 @Transactional public SubscriptionResponse update(UUID id,SubscriptionRequest r){var s=find(id);s.update(clean(r.name()),clean(r.provider()),money(r.amount()),r.currency(),r.periodicity(),r.nextChargeDate(),r.renewalDate(),r.status(),optional(r.category()),optional(r.notes()),optional(r.managementUrl()));return SubscriptionResponse.from(subscriptions.save(s));}
 @Transactional public void delete(UUID id){subscriptions.delete(find(id));}
 @Transactional(readOnly=true) public SubscriptionSummaryResponse summary(){var active=subscriptions.findAllByUserIdAndStatus(currentUser.id(),SubscriptionStatus.ACTIVE);var grouped=new TreeMap<String,BigDecimal[]>();for(var s:active){var totals=grouped.computeIfAbsent(s.getCurrency(),k->new BigDecimal[]{BigDecimal.ZERO,BigDecimal.ZERO});totals[0]=totals[0].add(monthly(s));totals[1]=totals[1].add(annual(s));}var currencies=grouped.entrySet().stream().map(e->new CurrencySummaryResponse(e.getKey(),scale(e.getValue()[0]),scale(e.getValue()[1]))).toList();var limit=LocalDate.now().plusDays(30);var renewals=active.stream().filter(s->s.getRenewalDate()!=null&&!s.getRenewalDate().isAfter(limit)).sorted(Comparator.comparing(Subscription::getRenewalDate)).map(SubscriptionResponse::from).toList();return new SubscriptionSummaryResponse(currencies,renewals);}
 static BigDecimal monthly(Subscription s){return switch(s.getPeriodicity()){case WEEKLY->s.getAmount().multiply(BigDecimal.valueOf(52)).divide(BigDecimal.valueOf(12),2,RoundingMode.HALF_UP);case MONTHLY->s.getAmount();case QUARTERLY->s.getAmount().divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP);case YEARLY->s.getAmount().divide(BigDecimal.valueOf(12),2,RoundingMode.HALF_UP);};} static BigDecimal annual(Subscription s){return switch(s.getPeriodicity()){case WEEKLY->s.getAmount().multiply(BigDecimal.valueOf(52));case MONTHLY->s.getAmount().multiply(BigDecimal.valueOf(12));case QUARTERLY->s.getAmount().multiply(BigDecimal.valueOf(4));case YEARLY->s.getAmount();};}
 private Subscription find(UUID id){return subscriptions.findByIdAndUserId(id,currentUser.id()).orElseThrow(()->new ResourceNotFoundException("No se encontró la suscripción"));} private static BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);} private static BigDecimal scale(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);} private static String clean(String v){return v.trim();} private static String optional(String v){if(v==null)return null;var x=v.trim();return x.isEmpty()?null:x;}
}
